import torch
import torch_npu
import custom_ops_lib

class ModelNew(torch.nn.Module):
    """
    使用 AscendC 自定义核实现的 1x1 点卷积（无偏置）。
    """
    def __init__(self, in_channels: int, out_channels: int):
        super().__init__()
        # 权重形状与 nn.Conv2d 的 1x1 权重一致: [out_channels, in_channels, 1, 1]
